export const SCENARIO_BY_ID: Record<ScenarioId, Scenario> = Object.fromEntries(
  SCENARIOS.map((s) => [s.id, s]),
) as Record<ScenarioId, Scenario>;

/** Resolve "surprise" to a concrete scenario. */
export function resolveScenario(id: ScenarioId, week: number): Scenario {
  if (id !== 'surprise') return SCENARIO_BY_ID[id];
  const pool = SCENARIOS.filter((s) => s.id !== 'surprise' && s.id !== 'free' && s.minWeek <= Math.max(week, 5));
  return pool[Math.floor(Math.random() * pool.length)];
}

